  function normalizePerplexitySettings(settings) {
    const requested = PERPLEXITY_LEGACY_MODE_ALIASES[settings?.model] || settings?.model;
    const model = PERPLEXITY_MODEL_OPTIONS.includes(requested) ? requested : 'perplexity-computer';
    const tools = PERPLEXITY_TOOL_OPTIONS.includes(settings?.tools) ? settings.tools : 'desktop';
    return { model, tools };
  }

  function savePerplexitySettings() {
    state.perplexity = normalizePerplexitySettings(state.perplexity);
    localStorage.setItem('perplexityAgentSettings', JSON.stringify(state.perplexity));
  }

