    state.perplexity = normalizePerplexitySettings({ ...state.perplexity, [key]: value });
    savePerplexitySettings();
    renderInspector();
    const label = key === 'model'
      ? (PERPLEXITY_MODEL_LABELS[state.perplexity.model] || state.perplexity.model)
      : (PERPLEXITY_TOOL_LABELS[state.perplexity.tools] || state.perplexity.tools);
    toast(`Perplexity ${key === 'model' ? 'mode' : 'tools'}: ${label}`);
