    // as a produced document. Plain prose answers don't qualify — we don't want the
    // button on every long chat message.
    const headings = (text.match(/^#{1,6}\s+\S/gm) || []).length;
    const hasTable = /^\|.+\|\s*$/m.test(text) && /^\|?[\s:|-]*-{2,}[\s:|-]*\|?\s*$/m.test(text);
