    if (mime.startsWith('video/') || kind === 'video'
        || ['mp4','webm','mov','m4v'].includes(ext)) return 'video';
    if (mime.startsWith('audio/') || ['mp3','wav','ogg','m4a','aac'].includes(ext)) return 'audio';
