  // Refresh re-polls every sensor live (the GET runs the registry, it is not a cache
  // read). It only ever LOOKED dead: a silent reload of an unchanged board repaints
  // pixel-for-pixel. Spin the icon, hold it long enough to register, and say what the
  // board now reads. It does not clear flags — a status light you can switch off by
  // hand is not a status light.
  document.getElementById('controlRoomRefreshBtn')?.addEventListener('click', async (ev) => {
    const btn = ev.currentTarget;
    if (btn.getAttribute('aria-busy') === 'true') return;   // don't race a poll in flight
    btn.setAttribute('aria-busy', 'true');
    const started = Date.now();
    try {
      await loadControlRoom({ silent: true });
      const d = ControlRoom.data;
      if (d && d.ok) {
        const sensors = d.sensors || [];
        const worst = sensors.reduce((w, s) =>
          (CR_SEV_RANK[s.severity] || 0) > (CR_SEV_RANK[w] || 0) ? s.severity : w, 'green');
        toast(worst === 'green'
          ? 'Sensors re-polled — all systems nominal'
          : `Sensors re-polled — still ${worst}`);
      } else {
        toast('Refresh failed');
      }
    } finally {
      // The poll usually beats the eye. Hold the spinner ~450ms so the click reads as
      // an action rather than a no-op.
      const held = Math.max(0, 450 - (Date.now() - started));
      setTimeout(() => btn.removeAttribute('aria-busy'), held);
    }
  });
