  // Present the same persisted stream as three orthogonal workflow states.
  // "Needs you" is action state, while read/unread only divides routine updates
  // from history. This prevents a read decision from disappearing before it is
  // actually handled, and counts grouped threads instead of raw repeated events.
  function notifDisplayBuckets(notifs) {
    const all = notifs || [];
    const needsYou = groupNotifsForDisplay(all).needsYou;
    const routine = all.filter(n => !notifNeedsYou(n));
    const updates = groupNotifsForDisplay(routine.filter(n => !n.read)).groups;
    const history = groupNotifsForDisplay(routine.filter(n => !!n.read)).groups;
    return { needsYou, updates, history };
  }
  // Rapid-repeat collapse at record time: if the newest row is the SAME chat and
  // SAME routine event within `windowMs`, refresh it in place (one unread row)
  // instead of stacking a near-duplicate. Needs-you rows are never merged — each
  // demands its own attention. Returns { list, merged }; `list` is what to store.
  function notifRecordDedup(list, incoming, windowMs) {
    list = list || [];
    const top = list[0];
    const w = windowMs || 45000;
    if (top && incoming && incoming.chat_id
        && !notifNeedsYou(incoming) && !notifNeedsYou(top)
        && String(top.chat_id || '') === String(incoming.chat_id || '')
        && String(top.event || '') === String(incoming.event || '')
        && Math.abs((incoming.ts || 0) - (top.ts || 0)) <= w) {
      top.title = incoming.title || top.title;
      top.body = incoming.body || top.body;
      top.ts = incoming.ts || top.ts;
      top.id = incoming.id || top.id;
      top.read = false;
      return { list, merged: true };
    }
    return { list: [incoming, ...list], merged: false };
  }
