      id: (m.notif_id != null) ? String(m.notif_id) : ('n' + (m.ts || Date.now()) + '-' + Math.random().toString(36).slice(2, 7)),
      chat_id: (m.chat_id != null) ? String(m.chat_id) : '',
      chat_title: m.chat_title || '',
      title: m.title || 'New activity',
      body: m.body || '',
      event: m.event || '',
      severity: String(m.severity || 'info').toLowerCase(),
      agent_id: m.agent_id || '',
