    const muted = !notifAlertsOn();
    if (dot) {
      if (u > 0) { dot.textContent = u > 99 ? '99+' : String(u); dot.classList.remove('hidden'); }
      else dot.classList.add('hidden');
      // Mute the bubble colour when alerts are off, so the state reads at a glance.
      dot.style.background = muted ? 'var(--text-dim)' : 'var(--ember, #ff5c5c)';
    }
    setBellIcon(muted);
    const btn = document.getElementById('notifBellBtn');
